const rows = $input.all().map(i => i.json).filter(r => r && r.id);
const now = Date.now();
const tally = (arr, fn) => arr.reduce((acc, r) => { const k = fn(r) || 'Unknown'; acc[k] = (acc[k] || 0) + 1; return acc; }, {});
const open = rows.filter(r => !['RESOLVED', 'REJECTED', 'DUPLICATE'].includes(r.status));
const area = r => String(r.address || 'Unknown area').split(',')[0].trim() || 'Unknown area';
const topAreas = Object.entries(tally(open, area)).sort((a, b) => b[1] - a[1]).slice(0, 5).map(([name, count]) => ({ name, count }));
const age = r => now - new Date(r.created_at).getTime();
const stats = {
  total_complaints: rows.length,
  new_last_24h: rows.filter(r => age(r) <= 864e5).length,
  new_last_7d: rows.filter(r => age(r) <= 6048e5).length,
  open_complaints: open.length,
  open_critical: open.filter(r => r.severity === 'Critical').length,
  open_with_safety_risk: open.filter(r => r.safety_risk).length,
  by_status: tally(rows, r => r.status),
  by_severity: tally(rows, r => r.severity),
  by_category: tally(rows, r => r.category),
  top_open_areas: topAreas,
  includes_demo_rows: rows.filter(r => r.is_demo).length
};
const system = 'You write a short operational briefing (3 to 5 plain sentences, no markdown, no bullet points) for a city administrator, based ONLY on the JSON statistics provided. Use only the numbers given. Do not invent causes, trends, comparisons, locations or recommendations that the data does not support. If a count is zero, say so. If includes_demo_rows is greater than 0, mention that some records are demo data.';
return [{ json: { stats, gemini_body: { system_instruction: { parts: [{ text: system }] }, contents: [{ role: 'user', parts: [{ text: 'Statistics (JSON): ' + JSON.stringify(stats) }] }], generationConfig: { temperature: 0.2 } } } }];

const res = $input.first().json;
const parts = (res.candidates && res.candidates[0] && res.candidates[0].content && res.candidates[0].content.parts) || [];
const summary = parts.map(p => p.text || '').join('').trim();
if (!summary) throw new Error('Gemini returned no summary text');
return [{ json: { summary, stats: $('Aggregate').first().json.stats } }];
